function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return(string)$_SESSION['csrf'];}function csrfok(string $v):bool{return$v!==''&&hash_equals((string)($_SESSION['csrf']??''),$v);} $db=crt_db();if(!$db){http_response_code(503);exit('Database unavailable.');}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&csrfok((string)($_POST['csrf']??''))){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=(string)($_POST['action']??'');try{if(!$id)throw new RuntimeException('Invalid standby item.');if($action==='cancel'){$s=$db->prepare("UPDATE CRTSHT_Draw_Standby SET Status='cancelled' WHERE ID=? AND Status='standby'");$s->bind_param('i',$id);$s->execute();$s->close();$msg='Standby cancelled.';}elseif($action==='promote'){$db->begin_transaction();$lock=$db->query("SELECT GET_LOCK('crtsht_draw_capacity_v1',5) locked");$ok=$lock&&(int)($lock->fetch_assoc()['locked']??0)===1;if($lock)$lock->free();if(!$ok)throw new RuntimeException('Capacity lock unavailable.');$s=$db->prepare("SELECT * FROM CRTSHT_Draw_Standby WHERE ID=? AND Status='standby' FOR UPDATE");$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row)throw new RuntimeException('Standby item no longer available.');$r=$db->query("SELECT COUNT(*) total FROM CRTSHT_Draw_Entries e JOIN CRTSHT_Draw_Reservations r ON r.ID=e.ReservationID WHERE r.Status IN ('reserved','paid')");$used=$r?(int)($r->fetch_assoc()['total']??0):128;if($r)$r->free();$q=(int)$row['Quantity'];if($used+$q>CRTSHT_TOTAL)throw new RuntimeException('Not enough physical slots available yet.');$status='reserved';$unit=$q>0?(float)$row['TotalPrice']/$q:0.0;$total=(float)$row['TotalPrice'];$s=$db->prepare('INSERT INTO CRTSHT_Draw_Reservations (ReservationCode,DrawBatch,Quantity,UnitPrice,TotalPrice,Name,Email,Mobile,Address,PLZ,City,Country,Status,CreatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$created=(string)$row['CreatedAt'];$s->bind_param('ssiddsssssssss',$row['ReservationCode'],$row['DrawBatch'],$q,$unit,$total,$row['Name'],$row['Email'],$row['Mobile'],$row['Address'],$row['PLZ'],$row['City'],$row['Country'],$status,$created);if(!$s->execute())throw new RuntimeException('Could not create reservation.');$rid=(int)$s->insert_id;$s->close