ead><tbody><?php foreach($rows as $i=>$r):?><tr><td>#<?=($i+1)?><br><span class="muted"><?=e($r['CreatedAt'])?></span></td><td><strong><?=e($r['ReservationCode'])?></strong></td><td><?=e($r['Name'])?><br><a href="mailto:<?=e($r['Email'])?>"><?=e($r['Email'])?></a></td><td><?=$r['Quantity']?>×<br>CHF <?=e(number_format((float)$r['TotalPrice'],2,'.',"'"))?></td><td>DRAW <?=e($r['DrawBatch'])?></td><td><span class="pill"><?=e($r['Status'])?></span><?php if($r['PromotedReservationID']):?><br><a href="/crtshtdrwmng/index.php?id=<?=$r['PromotedReservationID']?>">Reservation #<?=$r['PromotedReservationID']?> ↗</a><?php endif;?></td><td><?php if($r['Status']==='standby'):?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['ID']?>"><input type="hidden" name="action" value="promote"><button>PROMOTE</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['ID']?>"><input type="hidden" name="action" value="cancel"><button>CANCEL</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></body></html>